#[cfg(test)]
mod tests {
    use super::*;

    fn synthetic_image() -> Vec<u8> {
        let mut bytes = vec![0u8; 32 + 72 + 24];
        for (offset, value) in [
            (0, 0xfeedfacfu32),
            (4, 0x100000c),
            (8, 2),
            (16, 2),
            (20, 96),
            (32, 0x19),
            (36, 72),
            (92, 5),
            (104, 0x1b),
            (108, 24),
        ] {
            bytes[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
        }
        bytes[40..46].copy_from_slice(b"__TEXT");
        bytes[56..64].copy_from_slice(&0x180547000u64.to_le_bytes());
        bytes[64..72].copy_from_slice(&0x3ea5cu64.to_le_bytes());
        bytes[72..80].copy_from_slice(&0x147000u64.to_le_bytes());
        bytes[112..128].fill(1);
        bytes
    }

    #[test]
    fn f247_shared_cache_image_uses_virtual_slide() {
        let bytes = synthetic_image();
        let image = parse_image(0x190000000, &bytes).unwrap();
        assert_eq!(image.executable, vec![0x190000000..0x19003ea5c]);
        assert_eq!(image.uuid, [1; 16]);
        // Moving the resident base changes addresses, never instruction words.
        let moved = parse_image(0x1a0000000, &bytes).unwrap();
        assert_eq!(moved.executable, vec![0x1a0000000..0x1a003ea5c]);
        for len in 0..bytes.len() {
            assert!(parse_image(0x190000000, &bytes[..len]).is_err());
        }
        for offset in [0, 4, 16, 20, 36, 108] {
            let mut changed = bytes.clone();
            changed[offset..offset + 4].copy_from_slice(&u32::MAX.to_le_bytes());
            assert!(parse_image(0x190000000, &changed).is_err());
        }
        assert!(parse_image(usize::MAX - 2, &bytes).is_err());
    }

    #[test]
    fn f247_installed_current_witness() {
        if std::env::var_os("UMBRA_INTEGRATION_REQUIRED").is_none() {
            eprintln!("SKIP: installed witness requires the provisioned current host");
            return;
        }
        let kernel = image(KERNEL_IMAGE).expect("kernel image");
        let c = image(C_IMAGE).expect("C image");
        let profile = Profile {
            architecture: "arm64".into(),
            product_version: sysctl("kern.osproductversion").unwrap(),
            build: sysctl("kern.osversion").unwrap(),
            release: sysctl("kern.osrelease").unwrap(),
            kernel: sysctl("kern.version").unwrap(),
            image_uuid: kernel.uuid,
        };
        assert!(
            current_identity(&profile, &c.uuid),
            "{profile:?} C={:?}",
            c.uuid
        );
        for witness in CURRENT_CODE {
            let bytes = code_observation(&kernel, witness.symbol, witness.bytes.len())
                .unwrap_or_else(|e| panic!("{}: {e}", witness.symbol.to_string_lossy()));
            assert_eq!(bytes, witness.bytes, "{}", witness.symbol.to_string_lossy());
        }
        let attributes = observe_attributes(&kernel).expect("attribute observation");
        for (index, (actual, expected)) in attributes.iter().zip(expected_attributes()).enumerate()
        {
            assert_eq!(actual, &expected, "setter case {index}");
        }
        let actions = observe_actions(&kernel).expect("action observation");
        assert_eq!(actions, expected_actions());
        assert_eq!(
            qualify_current(&profile).unwrap().id,
            crate::spawn::CURRENT.id
        );
        eprintln!(
            "RAN: exact identities, 67 code ranges, 10 fresh attribute cases, 65 action counts, seven action tags and two port actions"
        );
    }

    #[test]
    fn f247_witness_rejects_each_changed_component() {
        let mut code: Vec<_> = CURRENT_CODE.iter().map(|w| w.bytes.to_vec()).collect();
        assert!(validate_code(&code).is_ok());
        for i in 0..code.len() {
            for j in 0..code[i].len() {
                code[i][j] ^= 1;
                assert!(validate_code(&code).is_err(), "code range {i} byte {j}");
                code[i][j] ^= 1;
            }
            let byte = code[i].pop().unwrap();
            assert!(validate_code(&code).is_err());
            code[i].push(byte);
        }
        code.pop();
        assert!(validate_code(&code).is_err());
        let mut attributes = expected_attributes();
        let actions = expected_actions();
        assert!(validate_behavior(&attributes, &actions).is_ok());
        for i in 0..attributes.len() {
            for j in 0..256 {
                attributes[i][j] ^= 1;
                assert!(
                    validate_behavior(&attributes, &actions).is_err(),
                    "attribute case {i} byte {j}"
                );
                attributes[i][j] ^= 1;
            }
        }
        for i in 0..actions.headers.len() {
            let mut changed = expected_actions();
            changed.headers[i].0 += 1;
            assert!(validate_behavior(&attributes, &changed).is_err());
            let mut changed = expected_actions();
            changed.headers[i].1 += 1;
            assert!(validate_behavior(&attributes, &changed).is_err());
        }
        for i in 0..actions.fields.len() {
            for j in 0..actions.fields[i].len() {
                let mut changed = expected_actions();
                changed.fields[i][j] ^= 1;
                assert!(validate_behavior(&attributes, &changed).is_err());
            }
        }
        for i in 0..actions.ports.len() {
            let mut changed = expected_actions();
            changed.ports[i] ^= 1;
            assert!(validate_behavior(&attributes, &changed).is_err());
        }
    }

    #[test]
    fn f247_current_identity_has_no_missing_or_changed_wildcards() {
        let profile = Profile {
            architecture: "arm64".into(), product_version: "27.2.1".into(), build: "26B131".into(),
            release: "27.2.0".into(), kernel: "Darwin Kernel Version 27.2.0: Wed Oct 14 23:47:07 PDT 2026; root:xnu-13432.41.4~25/RELEASE_ARM64_T8132".into(),
            image_uuid: [0xf2,0xbc,0xeb,0x9a,0x0f,0xec,0x3c,0x92,0xb6,0xea,0x8e,0x37,0x15,0x70,0x50,0xa8],
        };
        let c = [
            0x4b, 0xf4, 0x7e, 0xbb, 0x4c, 0xd0, 0x3f, 0x4a, 0x99, 0x5a, 0x71, 0x7b, 0x85, 0x50,
            0xcb, 0x12,
        ];
        assert!(current_identity(&profile, &c));
        for i in 0..5 {
            for value in ["", "different"] {
                let mut changed = profile.clone();
                let fields = [
                    &mut changed.architecture,
                    &mut changed.product_version,
                    &mut changed.build,
                    &mut changed.release,
                    &mut changed.kernel,
                ];
                *fields.into_iter().nth(i).unwrap() = value.into();
                assert!(!current_identity(&changed, &c));
            }
        }
        for i in 0..16 {
            let mut changed = profile.clone();
            changed.image_uuid[i] ^= 1;
            assert!(!current_identity(&changed, &c));
            let mut changed_c = c;
            changed_c[i] ^= 1;
            assert!(!current_identity(&profile, &changed_c));
        }
    }
}
